-- Wasl Islamic (وصل الإسلامية) — Automated Release Announcements & Changelog History
-- Stores verified production-deployed releases generated by the D7 intelligent analyzer.
-- Visitors can ONLY read releases with release_status = 'published' via Row Level Security.

CREATE TABLE IF NOT EXISTS public.platform_releases (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  commit_sha TEXT NOT NULL UNIQUE,
  previous_commit_sha TEXT,
  release_version TEXT NOT NULL,
  title_ar TEXT NOT NULL,
  summary_ar TEXT NOT NULL,
  categories JSONB NOT NULL DEFAULT '[]'::jsonb,
  highlights_count INTEGER NOT NULL DEFAULT 0,
  release_status TEXT NOT NULL DEFAULT 'pending'
    CHECK (release_status IN ('pending', 'published', 'failed', 'skipped')),
  deployment_target TEXT NOT NULL DEFAULT 'cloudflare',
  deployment_check_id TEXT,
  deployment_url TEXT,
  deployed_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_platform_releases_published_date
  ON public.platform_releases (release_status, deployed_at DESC);

ALTER TABLE public.platform_releases ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Public read published platform_releases" ON public.platform_releases;
CREATE POLICY "Public read published platform_releases"
  ON public.platform_releases FOR SELECT
  USING (release_status = 'published');
